// Turns the DinkDesk ticket.created payload into a Jira create-issue body (REST API v3).
const body = $json.body;
const t = body.data;
const jira = body.jira;
const para = (text) => ({ type: 'paragraph', content: text ? [{ type: 'text', text: String(text) }] : [] });
const who = t.requester || {};
const lines = [
  t.description,
  `Priority: ${t.priority} | Category: ${t.category} | System: ${t.affected_system} | Branch: ${t.club_code || 'not set'}`,
  `Requested by ${who.display_name || 'unknown'} (${who.role || 'unknown role'}, ${who.email || 'no email'}) through DinkDesk ticket ${t.ticket_number}.`,
];
return [{
  json: {
    ticket_number: t.ticket_number,
    base_url: String(jira.base_url || '').replace(/\/$/, ''),
    jira_body: {
      fields: {
        project: { key: jira.project_key },
        issuetype: { name: jira.issue_type },
        summary: `[${t.ticket_number}] ${t.summary}`.slice(0, 250),
        description: { type: 'doc', version: 1, content: lines.map(para) },
      },
    },
  },
}];
